import { useEffect, useState } from "react";

function useCurrentTime() {

  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {

    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    return () => {
      clearInterval(timer);
    };

  }, []);

  return currentTime;
}

export default useCurrentTime;
